# The classical steps of Shor's factoring algorithm, with a TOY stand-in for the quantum step.
# A quantum computer's only job is order finding. Here it is brute force, which only works for tiny n.
from math import gcd

def order(a: int, n: int) -> int:
    """Smallest r > 0 with a^r = 1 (mod n). This is the step a quantum computer does efficiently."""
    r, x = 1, a % n
    while x != 1:
        x = x * a % n
        r += 1
    return r

def shor_post_processing(n: int, a: int):
    if gcd(a, n) > 1:
        return gcd(a, n), n // gcd(a, n)          # lucky: a already shares a factor with n
    r = order(a, n)                                # <- quantum step in the real algorithm
    if r % 2 == 1:
        return None                                # failure: try another a
    b = pow(a, r // 2, n)
    if b == n - 1:                                 # b = -1 (mod n): failure, try another a
        return None
    return gcd(b - 1, n), gcd(b + 1, n)

n = 15
for a in (2, 4, 7, 11, 14):
    print(f"a = {a:2d}: order = {order(a, n)} ->", shor_post_processing(n, a) or "retry with another a")

# Grover's algorithm searches N items in about sqrt(N) steps, so an exhaustive search over a k-bit key
# drops from about 2^k classical trials to about 2^(k/2) quantum steps.
print("key bits | classical trials | quantum steps (Grover)")
for bits in (128, 192, 256):
    print(f"   {bits}   |      2^{bits}      |      2^{bits // 2}")

# NIST's five PQC security categories are defined by reference to these same benchmarks.
categories = {1: "key search on AES-128", 2: "collision search on SHA-256", 3: "key search on AES-192",
              4: "collision search on SHA-384", 5: "key search on AES-256"}
for level, benchmark in categories.items():
    print(f"category {level}: at least as hard as {benchmark}")
